    wire unused_s5_pins = ^{wbs_wb_CTI, wbs_wb_BTE};
    assign slv_err_raw[5] = (|s5_sts_rd.err_mask) || (|s5_sts_wr.err_mask);

    // =========================================================================
    // Device under test
