        .l5s_axil_awid (l5s_axil_awid[6:0]),
        .l5s_axil_awuser,
        .l5s_axil_awtrace,
        .l5s_axil_wuser,
        .l5s_axil_wpoison,
        .l5s_axil_bid (l5s_axil_bid[6:0]),
        .l5s_axil_buser,
